const STORAGE_KEY = 'smartpickshop-promotion-engine-progress-v2';
const UI_KEY = 'smartpickshop-promotion-engine-ui-v2';
const routes = PROMOTION_DATA.routes;
const byId = Object.fromEntries(routes.map(r => [r.ID, r]));
let progress = loadJson(STORAGE_KEY, {});
let uiState = loadJson(UI_KEY, {view:'dashboard'});

function loadJson(key, fallback){try{const v=JSON.parse(localStorage.getItem(key));return v ?? fallback}catch{return fallback}}
function saveProgress(){localStorage.setItem(STORAGE_KEY, JSON.stringify(progress)); renderDashboard(); renderWorkspace();}
function esc(v=''){return String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]))}
function pct(n,d){return d?Math.round(n/d*100):0}
function routeState(id){return progress[id] || {progress:'Not Started',project:'',receipt:'',notes:'',updated:''}}
function setRouteState(id, patch){progress[id]={...routeState(id),...patch,updated:new Date().toISOString()};saveProgress()}

function setupTabs(){document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>switchView(b.dataset.view)));switchView(uiState.view||'dashboard')}
function switchView(name){document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.view===name));document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));document.getElementById(name+'View')?.classList.add('active');uiState.view=name;localStorage.setItem(UI_KEY,JSON.stringify(uiState));if(name==='workspace')renderWorkspace()}

function setupNotice(){document.getElementById('rebuildNotice').textContent=PROMOTION_DATA.meta.reconstructionNote}

function setupFilters(){const statuses=[...new Set(routes.map(r=>r.Status))].sort();const platforms=[...new Set(routes.map(r=>r.Platform))].sort();fillSelect('statusFilter',statuses);fillSelect('platformFilter',platforms);['searchInput','statusFilter','platformFilter','progressFilter'].forEach(id=>document.getElementById(id).addEventListener(id==='searchInput'?'input':'change',renderRoutes))}
function fillSelect(id,values){const s=document.getElementById(id);values.forEach(v=>{const o=document.createElement('option');o.value=o.textContent=v;s.appendChild(o)})}

function renderRoutes(){
  const q=document.getElementById('searchInput').value.trim().toLowerCase();const st=document.getElementById('statusFilter').value;const pf=document.getElementById('platformFilter').value;const pg=document.getElementById('progressFilter').value;
  const filtered=routes.filter(r=>{const blob=Object.values(r).join(' ').toLowerCase();return(!q||blob.includes(q))&&(!st||r.Status===st)&&(!pf||r.Platform===pf)&&(!pg||routeState(r.ID).progress===pg)});
  document.getElementById('routeCount').textContent=`${filtered.length} of ${routes.length} tracked routes`;
  const grid=document.getElementById('routesGrid');grid.innerHTML='';const t=document.getElementById('routeTemplate');
  filtered.forEach(r=>{const el=t.content.firstElementChild.cloneNode(true);el.querySelector('.route-id').textContent=r.ID;el.querySelector('.priority-pill').textContent='Priority '+r.Priority;el.querySelector('.route-title').textContent=r['Channel / Route'];el.querySelector('.platform').textContent=r.Platform;el.querySelector('.status-pill').textContent=r.Status;el.querySelector('.cost-pill').textContent=r['Cost Path'];
    const details=[['Audience',r.Audience],['Fit',r['Project Fit']],['Rule',r['Rules / Permission']],['Next',r['Next Action']],['Verified',r['Verified Date']]];el.querySelector('.route-details').innerHTML=details.map(([a,b])=>`<dt>${esc(a)}</dt><dd>${esc(b)}</dd>`).join('');
    const s=routeState(r.ID);const ps=el.querySelector('.progress-select');ps.value=s.progress;ps.addEventListener('change',e=>setRouteState(r.ID,{progress:e.target.value}));const pi=el.querySelector('.project-input');pi.value=s.project;pi.addEventListener('change',e=>setRouteState(r.ID,{project:e.target.value.trim()}));const ri=el.querySelector('.receipt-input');ri.value=s.receipt;ri.addEventListener('change',e=>setRouteState(r.ID,{receipt:e.target.value.trim()}));const ni=el.querySelector('.notes-input');ni.value=s.notes;ni.addEventListener('change',e=>setRouteState(r.ID,{notes:e.target.value.trim()}));
    el.querySelector('.direct-link').href=r['Direct URL'];el.querySelector('.source-link').href=r['Source URL'];grid.appendChild(el)});
  if(!filtered.length)grid.innerHTML='<div class="panel empty">No routes match those filters.</div>';
}

function renderDashboard(){
  const target=document.getElementById('dashboardView');const statusCounts={};routes.forEach(r=>statusCounts[r.Status]=(statusCounts[r.Status]||0)+1);const progCounts={};routes.forEach(r=>{const p=routeState(r.ID).progress;progCounts[p]=(progCounts[p]||0)+1});const completed=(progCounts.Published||0)+(progCounts.Submitted||0);const free=routes.filter(r=>r.Status==='Ready — Free').length;const paid=routes.filter(r=>r.Status==='Ready — Paid').length;const permission=routes.filter(r=>r.Status==='Permission Check').length;
  target.innerHTML=`<div class="section-head"><div><p class="eyebrow">CHECKPOINT · ${esc(PROMOTION_DATA.meta.rebuilt)}</p><h2>Command Center</h2></div><p>${esc(PROMOTION_DATA.meta.sourceRouteCount)} verified workbook routes + ${routes.length-PROMOTION_DATA.meta.sourceRouteCount} reverified additions. Research is separated from actual submission progress.</p></div>
  <div class="kpi-grid"><div class="panel kpi"><strong>${routes.length}</strong><span>Tracked routes</span></div><div class="panel kpi"><strong>${free}</strong><span>Ready — Free</span></div><div class="panel kpi"><strong>${paid}</strong><span>Ready — Paid</span></div><div class="panel kpi"><strong>${permission}</strong><span>Permission Check</span></div><div class="panel kpi"><strong>${completed}</strong><span>Submitted / published</span></div></div>
  <div class="dashboard-grid"><div class="panel dash-block"><h3>Evidence status</h3>${Object.entries(statusCounts).map(([k,v])=>`<div class="bar-row"><span>${esc(k)}</span><div class="bar"><i style="width:${pct(v,routes.length)}%"></i></div><b>${v}</b></div>`).join('')}</div><div class="panel dash-block"><h3>Workspace progress</h3>${['Not Started','Ready','In Progress','Submitted','Published','Blocked','Skipped'].map(k=>`<div class="bar-row"><span>${k}</span><div class="bar"><i style="width:${pct(progCounts[k]||0,routes.length)}%"></i></div><b>${progCounts[k]||0}</b></div>`).join('')}</div></div>
  <div class="dashboard-grid"><div class="panel dash-block"><h3>Execution order</h3><ol><li>Confirm one genuinely live product/offer.</li><li>Use free software routes first.</li><li>Log submission receipts and public URLs.</li><li>Use communities only where participation/pitching is allowed.</li><li>Keep paid routes parked until free-route results exist.</li></ol></div><div class="panel dash-block"><h3>Hard rules</h3><ul class="rule-list">${PROMOTION_DATA.meta.hardRules.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></div>`;
}

function renderWorkspace(){const rows=routes.map(r=>{const s=routeState(r.ID);return `<tr><td><b>${esc(r.ID)}</b><br><span class="muted">${esc(r.Platform)}</span></td><td>${esc(r['Channel / Route'])}<br><span class="tiny-pill">${esc(r.Status)}</span></td><td><select data-id="${r.ID}" data-field="progress">${['Not Started','Ready','In Progress','Submitted','Published','Blocked','Skipped'].map(x=>`<option${x===s.progress?' selected':''}>${x}</option>`).join('')}</select></td><td><input data-id="${r.ID}" data-field="project" value="${esc(s.project)}" placeholder="Project / offer"></td><td><input data-id="${r.ID}" data-field="receipt" value="${esc(s.receipt)}" placeholder="Receipt / live URL"></td><td><textarea rows="2" data-id="${r.ID}" data-field="notes" placeholder="Notes">${esc(s.notes)}</textarea></td><td>${s.updated?new Date(s.updated).toLocaleString():'—'}</td></tr>`}).join('');document.getElementById('workspaceTableWrap').innerHTML=`<table class="workspace-table"><thead><tr><th>Route</th><th>Channel</th><th>Progress</th><th>Project</th><th>Receipt</th><th>Notes</th><th>Updated</th></tr></thead><tbody>${rows}</tbody></table>`;document.querySelectorAll('#workspaceTableWrap [data-id]').forEach(el=>el.addEventListener('change',e=>setRouteState(e.target.dataset.id,{[e.target.dataset.field]:e.target.value.trim()})))}

function renderActions(){const target=document.getElementById('actionsView');target.innerHTML=`<div class="section-head"><div><p class="eyebrow">EXECUTION QUEUE</p><h2>Next Actions</h2></div><p>Research does not count as distribution. This queue starts where the paperwork stops being decorative.</p></div><div class="action-list">${PROMOTION_DATA.nextActions.sort((a,b)=>Number(a.Order)-Number(b.Order)).map(a=>`<article class="panel action"><div class="action-head"><h3>${esc(a.Order)}. ${esc(a.Action)}</h3><span class="tiny-pill">${esc(a.Status)}</span></div><p>${esc(a['Exact Task'])}</p><p class="muted">Why now: ${esc(a['Why Now'])}</p></article>`).join('')}</div>`}

function renderDrafts(){const target=document.getElementById('draftsView');target.innerHTML=`<div class="section-head"><div><p class="eyebrow">TAILORED COPY</p><h2>Drafts</h2></div><p>Scaffolds only. Replace brackets with verified facts and obey each route's rules before posting.</p></div><div class="draft-list">${PROMOTION_DATA.drafts.map(d=>`<article class="panel draft"><div class="draft-head"><div><h3>${esc(d.Route)}</h3><span class="muted">${esc(d['Draft Type'])}</span></div><button class="button secondary copy-draft" data-copy="${esc(d['Draft ID'])}">Copy</button></div><pre class="draft-copy" id="${esc(d['Draft ID'])}">${esc(d['Copy Scaffold'])}</pre><p class="callout">${esc(d['Guardrail / Edit Before Use'])}</p></article>`).join('')}</div>`;document.querySelectorAll('.copy-draft').forEach(b=>b.addEventListener('click',async()=>{const text=document.getElementById(b.dataset.copy).innerText;await navigator.clipboard.writeText(text);const old=b.textContent;b.textContent='Copied';setTimeout(()=>b.textContent=old,900)}))}

function renderEvidence(){const target=document.getElementById('evidenceView');target.innerHTML=`<div class="section-head"><div><p class="eyebrow">SOURCE LEDGER</p><h2>Evidence & Rules</h2></div><p>${PROMOTION_DATA.sources.length} source checks are carried in this checkpoint. Re-check immediately before any real submission.</p></div><div class="evidence-list">${PROMOTION_DATA.sources.map(s=>`<article class="panel evidence"><div class="evidence-head"><h3>${esc(s['Source / Route'])}</h3><span class="tiny-pill">${esc(s.Confidence)}</span></div><p>${esc(s['Verified Claim'])}</p><p class="muted">Checked ${esc(s.Checked)} · <a href="${esc(s.URL)}" target="_blank" rel="noopener">Open source</a></p></article>`).join('')}</div>`}

function exportProgress(){const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),checkpoint:PROMOTION_DATA.meta.checkpoint,progress},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='promotion-engine-progress.json';a.click();URL.revokeObjectURL(a.href)}
function importProgress(file){const r=new FileReader();r.onload=()=>{try{const obj=JSON.parse(r.result);progress=obj.progress||obj;saveProgress();renderRoutes();alert('Progress imported.')}catch{alert('That file is not valid Promotion Engine progress JSON.')}};r.readAsText(file)}
function resetProgress(){if(confirm('Reset all local route progress, notes, projects and receipt URLs?')){progress={};saveProgress();renderRoutes()}}

document.getElementById('exportBtn').addEventListener('click',exportProgress);document.getElementById('importInput').addEventListener('change',e=>e.target.files[0]&&importProgress(e.target.files[0]));document.getElementById('resetBtn').addEventListener('click',resetProgress);
setupNotice();setupTabs();setupFilters();renderRoutes();renderDashboard();renderWorkspace();renderActions();renderDrafts();renderEvidence();